do $m$ declare s text; begin select pg_get_functiondef('facodi.kf_push_operational_snapshot()'::regprocedure) into s;
s:=replace(s,'''schema_version'',1,','''schema_version'',1,
 ''kf_assurance_v1'',jsonb_build_object(''mirror'',facodi.kf_mirror_health_v1(),''resource_av'',jsonb_build_object(''task_id'',125,''expected'',5,''scope'',''partial_av_cross_provider'',''job_ids'',(select coalesce(jsonb_agg(distinct a.id::text),''[]''::jsonb) from facodi.analysis_jobs a join facodi.video_classifications v on v.video_id=a.video_id and v.metadata->>''kf_av_evidence_job_id''=a.id::text join facodi.learning_objects o on o.id=a.learning_object_id where a.request_source=''kf_private_candidate_review_v1'' and a.status=''needs_review'' and a.result_payload->''kf_av_async''->>''outcome''=''partial_av_evidence'' and v.metadata->>''kf_av_consensus''=''cross_provider_strong_match'' and v.status=''needs_review'' and v.needs_review and o.status=''draft'' and not o.published and o.metadata->>''editorial_batch''=''facodi-kf-legacy-studio-20261127''))),');
if position('kf_assurance_v1' in s)=0 then raise exception 'Unexpected snapshot'; end if; execute s; end $m$;
revoke all on function facodi.kf_push_operational_snapshot() from public,anon,authenticated,service_role;
